commands:
# Get all SATA/AHCI controllers
 $ahciControllers = Get-CimInstance Win32_PnPEntity | Where-Object { $_.PNPClass -eq "IDE" -or $_.PNPClass -eq "SCSIAdapter" } | Select-Object -ExpandProperty PNPDeviceID

 foreach ($ctrl in $ahciControllers) {
  $msiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$ctrl\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
  if (Test-Path $msiKey) {
  Set-ItemProperty -Path $msiKey -Name "MSISupported" -Value 1
  }

  $affinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$ctrl\Device Parameters\Interrupt Management\Affinity Policy"
  if (Test-Path $affinityKey) {
  Set-ItemProperty -Path $affinityKey -Name "DevicePriority" -Value 0
  }
 }

